import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="card" style={styles.card}>
        <Text style={styles.name}>Утасгүй чихэвч</Text>
        <Text style={styles.price}>159,000₮</Text>
      </View>
      {/* энд бичнэ үү: картад сүүдэр нэм */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 32, backgroundColor: "#f8fafc" },
  card: { backgroundColor: "#fff", padding: 20, borderRadius: 16, gap: 6 },
  name: { fontSize: 16, fontWeight: "600" },
  price: { fontSize: 18, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);

